153:         const cmd = seat.queue.shift();
154:         if (cmd) {
155:           seat.held = { moveX: cmd.axes.x, jump: cmd.jump };
156:           seat.lastProcessedSeq = cmd.seq;
157:           seat.lastHumanInputTick = this.tickCount;
158:         } else if (
159:           this.tickCount - seat.lastHumanInputTick >=
160:           this.config.humanIdleAiTicks
161:         ) {
