165:           events.push({ type: "ai_takeover", seatId: seat.seatId });
166:         }
167:       } else {
168:         // Connected human packet returns control (input-commands.md).
169:         const cmd = seat.queue.shift();
170:         if (cmd && seat.connected) {
171:           seat.control = "human";
172:           seat.held = { moveX: cmd.axes.x, jump: cmd.jump };
173:           seat.lastProcessedSeq = cmd.seq;
174:           seat.lastHumanInputTick = this.tickCount;
175:           events.push({ type: "human_takeover", seatId: seat.seatId });
176:         } else {
