202:         carry: [],
203:         stunned: false,
204:       };
205:       if (seat.displayName !== undefined) hauler.name = seat.displayName;
206:       return hauler;
207:     });
208:     return {
209:       tick: this.tickCount,
210:       phase: "level",
211:       levelId: this.level.id,
212:       levelsCompleted: 0,
213:       levelsAfterHoard: this.config.levelsAfterHoard,
214:       lastProcessedInputSeq,
215:       haulers,
216:       treasures: [],
217:       traps: [],
218:       switches: [],
219:     };
220:   }
