223:     return this.seats.map((seat) => {
224:       const pub: SeatPublic = {
225:         seatId: seat.seatId,
226:         occupied: seat.humanId !== undefined,
227:         control: seat.control,
228:         ready: false,
229:       };
230:       if (seat.displayName !== undefined) pub.displayName = seat.displayName;
231:       return pub;
232:     });
233:   }
