1: /**
2:  * Treasure lifecycle for the authoritative sim (simulation DESIGN §7).
3:  *
4:  * Every treasure instance is in exactly one place: carried by a seat, free in
5:  * the world, or destroyed (conservation invariant §7.4). This module owns the
6:  * free/projectile pool + physics; the Simulation owns carry stacks and grants
7:  * pickups (server is the sole grantor). Identity is rolled once at level load
8:  * via the pure rules catalog and never mutated afterward.
9:  */
10: import { getTreasureDef, rollTreasureDef, type Rarity } from "@dhaul/rules";
11: import type { LevelDefinition, TreasureSlot } from "@dhaul/levels";
12: import type { CarriedTreasureRef, TreasurePublic } from "@dhaul/protocol";
13: import type { Rng } from "@dhaul/rules";
14: import type { SolidGrid } from "./kinematics.js";
15: 
16: /** Uniform per-item weight for MVP (DESIGN §5.4 leaves the curve tunable). */
17: export const ITEM_WEIGHT = 1;
18: 
19: export type TreasureState = "free" | "carried" | "destroyed";
20: 
21: export interface TreasureRuntime {
22:   instanceId: string;
23:   defId: string;
24:   valueGp: number;
25:   rarity: Rarity;
26:   weight: number;
27:   stackableVisual: boolean;
28:   isChest: boolean;
29:   chestTable?: string;
30:   state: TreasureState;
31:   /** World px (center). Meaningful for free/projectile items. */
32:   x: number;
33:   y: number;
34:   vx: number;
35:   vy: number;
36:   /** Ticks a just-thrown/spilled item stays a live projectile before settling reads. */
37:   ownerSeatId?: number;
38: }
39: 
40: /** Half-extent of a loose treasure AABB in px. */
41: const T_HALF = 8;
42: const EPS = 0.001;
