44: export interface TreasurePhysicsConfig {
45:   gravity: number;
46:   maxFallSpeed: number;
47:   dt: number;
48:   /** Horizontal drag applied to loose items each tick (0..1 retained). */
49:   drag: number;
50: }
51: 
52: /** Build a runtime instance from a rolled def. */
53: function makeRuntime(
54:   instanceId: string,
55:   defId: string,
56:   x: number,
57:   y: number,
58: ): TreasureRuntime {
59:   const def = getTreasureDef(defId);
60:   if (!def) throw new Error(`treasure: unknown defId "${defId}"`);
61:   const rt: TreasureRuntime = {
62:     instanceId,
63:     defId,
64:     valueGp: def.baseValueGp,
65:     rarity: def.rarity,
66:     weight: ITEM_WEIGHT,
67:     stackableVisual: def.stackableVisual,
68:     isChest: def.isChest,
69:     state: "free",
70:     x,
71:     y,
72:     vx: 0,
73:     vy: 0,
74:   };
75:   if (def.chestTable) rt.chestTable = def.chestTable;
76:   return rt;
77: }
78: 
79: export class TreasureSystem {
80:   /** Every instance ever created this level, keyed by id (source of truth). */
81:   private readonly items = new Map<string, TreasureRuntime>();
82:   private nextId = 0;
83: 
84:   constructor(private readonly phys: TreasurePhysicsConfig) {}
85: 
86:   /**
87:    * Roll identities for every slot with the seeded stream. Uniques/set pieces
88:    * already in play are excluded so no live duplicate spawns (§7.1).
89:    */
90:   spawnFromLevel(level: LevelDefinition, rng: Rng, idPrefix: string): void {
91:     const excluded: string[] = [];
92:     level.treasureSlots.forEach((slot: TreasureSlot, i: number) => {
93:       const def = rollTreasureDef(rng, "world", { excludedDefIds: excluded });
94:       if (def.unique || def.rarity === "set") excluded.push(def.id);
95:       const bs = level.blockSizePx;
96:       const instanceId = `${idPrefix}:t${i}`;
97:       this.items.set(
98:         instanceId,
99:         makeRuntime(instanceId, def.id, slot.x * bs + bs / 2, slot.y * bs + bs / 2),
100:       );
101:       this.nextId = i + 1;
102:     });
103:   }
