113:   /** Def ids currently carried or free (for unique-in-play roll exclusion). */
114:   liveUniqueDefIds(): string[] {
115:     const ids: string[] = [];
116:     for (const t of this.items.values()) {
117:       if (t.state !== "destroyed" && (t.rarity === "unique" || t.rarity === "set")) {
118:         ids.push(t.defId);
119:       }
