132:       const dx = t.x - x;
133:       const dy = t.y - y;
134:       if (dx * dx + dy * dy > radius * radius) continue;
135:       if (
136:         best === undefined ||
137:         t.valueGp > best.valueGp ||
138:         (t.valueGp === best.valueGp && t.instanceId < best.instanceId)
139:       ) {
