1: /**
2:  * Deterministic PRNG for the simulation (treasure rolls, fork picks).
3:  * Implements the rules-package {@link Rng} interface so `rollTreasureDef` etc.
4:  * consume a single seeded stream (simulation DESIGN §4.3). Pure + dependency
5:  * free; never calls Math.random()/Date.now().
6:  *
7:  * mulberry32: fast, well-distributed 32-bit generator. Seed derives from the
8:  * session rngSeed (+ optional sub-stream salt for level-scoped rolls).
9:  */
10: import type { Rng } from "@dhaul/rules";
11: 
12: export class Mulberry32 implements Rng {
13:   private state: number;
14: 
15:   constructor(seed: number) {
16:     // Coerce to uint32; a zero seed still produces a usable stream.
17:     this.state = seed >>> 0;
18:   }
19: 
20:   next(): number {
21:     this.state = (this.state + 0x6d2b79f5) >>> 0;
22:     let t = this.state;
23:     t = Math.imul(t ^ (t >>> 15), t | 1);
24:     t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
25:     return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
26:   }
27: 
28:   nextInt(maxExclusive: number): number {
29:     if (maxExclusive <= 0) return 0;
30:     return Math.floor(this.next() * maxExclusive);
31:   }
32: }
33: 
34: /** Combine a base seed with a string salt (e.g. level id) into a uint32 seed. */
35: export function deriveSeed(base: number, salt: string): number {
36:   let h = base >>> 0;
37:   for (let i = 0; i < salt.length; i++) {
38:     h = (Math.imul(h ^ salt.charCodeAt(i), 0x01000193) + 1) >>> 0;
39:   }
40:   return h >>> 0;
41: }
